package com.gymmind.membership.domain.model; import com.gymmind.shared.persistence.TenantScopedEntity; import jakarta.persistence.*; import java.time.Instant; @Entity @Table(name="member_membership") public class MemberMembership extends TenantScopedEntity{ @Column(name="member_id",nullable=false)private Long memberId;@Column(name="package_id",nullable=false)private Long packageId;@Column(name="remaining_count")private Integer remainingCount;@Column(name="starts_at",nullable=false)private Instant startsAt;@Column(name="expires_at")private Instant expiresAt;@Enumerated(EnumType.STRING)@Column(nullable=false,length=16)private MemberMembershipStatus status=MemberMembershipStatus.ACTIVE;protected MemberMembership(){}private MemberMembership(Long t,Long m,Long p,Integer c,Instant s,Instant e){super(t);if(m==null||p==null||s==null)throw new IllegalArgumentException("Invalid membership");memberId=m;packageId=p;remainingCount=c;startsAt=s;expiresAt=e;}public static MemberMembership create(Long t,Long m,Long p,Integer c,Instant s,Instant e){return new MemberMembership(t,m,p,c,s,e);}public void consume(){if(remainingCount==null||remainingCount<=0)throw new IllegalStateException("No remaining entitlement");remainingCount--;}public Long getMemberId(){return memberId;}public Long getPackageId(){return packageId;}public Integer getRemainingCount(){return remainingCount;}public Instant getStartsAt(){return startsAt;}public Instant getExpiresAt(){return expiresAt;}public MemberMembershipStatus getStatus(){return status;}}
